'use strict';
const assert=require('node:assert/strict'),express=require('express'),{randomUUID}=require('node:crypto');
async function qualifyListingsCatalog({identity,migration,scope,controlledDisplay=false}){
 const {seedWorkshopPlatform}=require('../../server/database/postgres/workshopPlatformSeed'),catalog=require('../../server/config/secureshopCurriculum'),ids=require('../helpers/secureshopListingsCurriculumCandidate').candidates.map(c=>c.id),key=catalog.WORKSHOP_KEY;
 assert.ok(ids.every(id=>catalog.QUALIFIED_OBJECTIVE_IDS.includes(id)));
 process.env.IDENTITY_DATABASE_URL=process.env.LISTINGS_IDENTITY_RUNTIME_URL;process.env.PLATFORM_DATABASE_ENGINE='postgres';process.env.JWT_SECRET='owned-listings-catalog-'+randomUUID();
 const adapter=require('../../server/services/postgresIdentityAdapter').getPostgresIdentityAdapter(),users=adapter.repository,config=require('../../server/database/postgres/workshopConfigRepository').createWorkshopConfigRepository(identity,{isSecureShopReady:()=>true}),progress=require('../../server/database/postgres/workshopProgressRepository').createWorkshopProgressRepository(identity);
 let server;try{
  assert.deepEqual((await identity.query('SELECT objective_id FROM workshop_platform.objectives WHERE workshop_key=$1 AND catalog_active ORDER BY ordinal',[key])).rows.map(r=>r.objective_id),catalog.OBJECTIVES.map(o=>o.id));
  const credential=await users.findCredentialById(scope.platformOwnerId),student=await adapter.createSession(credential,{get:()=>'',ip:'127.0.0.1'}),adminUser=await users.createUser({username:'listings-admin-'+randomUUID().slice(0,8),email:randomUUID()+'@example.invalid',passwordHash:await require('bcryptjs').hash('owned-fixture',4)});
  await migration.query("UPDATE identity.users SET role='super_admin',admin_level=2,email_verified=1 WHERE id=$1",[adminUser.id]);for(const permission of ['user_management','challenge_management','system_config','manage_progress','system_logs','view_analytics'])await users.grantPermission({userId:adminUser.id,permission,grantedBy:adminUser.id});const admin=await adapter.createSession(await users.findCredentialById(adminUser.id),{get:()=>'',ip:'127.0.0.1'});
  const app=express();app.use(express.json());const auth=require('../../server/middleware/postgresAdminAuth').createPostgresAdminAuth(adapter);
  app.use('/api/admin/exercises',require('../../server/routes/adminExercises').createAdminExercisesRouter({service:config,onCommitted:()=>{},onContentCommitted:async()=>{}}));
  const content=require('../../server/routes/postgresWorkshopContent');app.use('/api/hints',content.createPostgresHintsRouter(config));app.use('/api/solutions',content.createPostgresSolutionsRouter(config));app.use('/api/workshop/config',require('../../server/routes/workshopConfig').createWorkshopConfigRouter(config));app.use('/api/workshop',require('../../server/routes/postgresWorkshop').createPostgresWorkshopRouter({stores:{pool:identity,config,progress},authenticateToken:auth.authenticateToken}));
  server=await new Promise(r=>{const s=app.listen(0,'127.0.0.1',()=>r(s));});const origin='http://127.0.0.1:'+server.address().port;
  async function request(route,{token=student.token,enabled}={}){const response=await fetch(origin+route,{method:enabled===undefined?'GET':'PATCH',headers:{authorization:'Bearer '+token,'content-type':'application/json'},...(enabled===undefined?{}:{body:JSON.stringify({enabled})})});return{status:response.status,body:await response.json()};}
  await config.setAllExerciseVisibility(false);await config.setExerciseVisibility(key,true);await config.setAllObjectiveVisibility(key,false);
  for(const id of ids){const route=`/api/admin/exercises/${key}/objectives/${id}`;
   assert.equal((await request(route,{enabled:true})).status,403);assert.equal((await request(route,{token:'invalid',enabled:true})).status,401);assert.equal((await request(route,{token:admin.token,enabled:true})).status,200);
  }
  for(const id of catalog.PENDING_OBJECTIVE_IDS)await assert.rejects(config.setObjectiveVisibility(key,id,true),{code:'OBJECTIVE_UNQUALIFIED'});
  await config.setMasterHintVisibility(key,true);await config.setMasterSolutionVisibility(key,true);
  for(const id of ids){const route=`/api/admin/exercises/${key}/objectives/${id}`,hint=`/api/hints/${key}/${id}`,solution=`/api/solutions/secureshop-agent-security/${id}`;
   for(const [h,s]of [[true,true],[false,true],[true,false],[false,false]]){assert.equal((await request(route+'/hint',{token:admin.token,enabled:h})).status,200);assert.equal((await request(route+'/solution',{token:admin.token,enabled:s})).status,200);assert.equal((await request(hint)).status,h?200:403);assert.equal((await request(solution)).status,s?200:403);}
  }
  await config.setMasterHintVisibility(key,true);await config.setMasterSolutionVisibility(key,true);
  const id=ids[0];await config.updateHintContent(key,id,{title:'Instructor Listings hint',hints:['Preserved instructor teaching content']});await config.updateSolutionContent(key,id,{title:'Instructor Listings solution',tips:['Preserved instructor tip']});
  await migration.query('UPDATE workshop_platform.objectives SET label=$1 WHERE workshop_key=$2 AND objective_id=$3',['Instructor Listings label',key,id]);
  const sql='SELECT objective_id,label,is_enabled,hint_enabled,solution_enabled,hint_content,solution_content FROM workshop_platform.objectives WHERE workshop_key=$1 AND objective_id=ANY($2::text[]) ORDER BY objective_id';const before=(await identity.query(sql,[key,ids])).rows;
  await seedWorkshopPlatform(migration);await seedWorkshopPlatform(migration);assert.deepEqual((await identity.query(sql,[key,ids])).rows,before,'Repeated seeds preserve instructor content and gates');
  await progress.recordHeartbeat({userId:scope.platformOwnerId,workshopKey:key,instanceScope:scope});await new Promise(resolve=>setTimeout(resolve,1200));await progress.recordHeartbeat({userId:scope.platformOwnerId,workshopKey:key,instanceScope:scope});
  const challenges=await request('/api/workshop/challenges'),projection=await request('/api/workshop/progress'),stats=await request('/api/workshop/student/stats'),time=await request('/api/workshop/time/summary');for(const r of[challenges,projection,stats,time])assert.equal(r.status,200);
  const c=challenges.body.challenges.find(r=>r.workshopKey===key),p=projection.body.challenges.find(r=>r.workshopKey===key);assert.deepEqual(c,p);assert.deepEqual(c.objectives.map(o=>o.id).sort(),[...ids].sort());assert.equal(c.objectiveCount,4);assert.equal(c.completedObjectiveCount,1);assert.deepEqual(c.objectives.filter(o=>o.completed).map(o=>o.id),['ss_listing_generated_browser_execution']);assert.ok(c.timeSpentSeconds>0);assert.equal(stats.body.totalObjectives,4);assert.equal(stats.body.completedObjectives,1);assert.equal(time.body.summary[key],c.timeSpentSeconds);
  const adminProjection=(await progress.getUsersProgress([scope.platformOwnerId])).get(scope.platformOwnerId).find(r=>r.workshopKey===key);assert.equal(adminProjection.completedObjectiveCount,1);assert.equal(adminProjection.timeSpentSeconds,c.timeSpentSeconds);
  await config.setExerciseVisibility(key,false);assert.equal((await request('/api/hints/'+key+'/'+id)).status,403);assert.equal((await request('/api/workshop/challenges')).body.challenges.some(r=>r.workshopKey===key),false);await config.setExerciseVisibility(key,true);
  const rendered=process.env.LISTINGS_RENDERED_CATALOG==='1'?await require('./secureshopListingsCatalogRendered').qualifyListingsCatalogRendered({app,origin,adapter,auth,config,progress,identity,student,admin,scope,projection:c}):null;
  return{status:'passed',candidateOnly:true,controlledDisplayCompletion:controlledDisplay,rendered,projectedCompletionIds:c.objectives.filter(o=>o.completed).map(o=>o.id),enabledObjectiveIds:ids,checks:['exact canonical catalog IDs','real authenticated admin mutations and student/invalid-session denial','all four independent hint/solution gate combinations','unrelated pending objectives denied','populated instructor content and visibility preserved on two seeds','matching learner/admin counts and nonzero time',controlledDisplay?'controlled display completion; no new model credit':'one authentic mounted browser completion projected','hidden exercise denies content and learner visibility'],projections:{challenges:c,stats:stats.body,time:time.body}};
 }finally{if(server){server.closeAllConnections();await new Promise(r=>server.close(r));}await require('../../server/database/postgres').closePostgresPools();}
}
module.exports={qualifyListingsCatalog};
